//! x86 target builtins (spec/landed/codegen/WP-630.md, WP-630): clang's
//! `checkTargetFeatures` for the call, then clang's lowering. The
//! builtins clang lowers to one `llvm.x86.*` call taking the arguments in
//! order are a table ([`crate::x86_intrinsics::MAP`], generated by
//! `scripts/gen-x86-builtins.py`); the SSE to SSE4.2 family builtins clang
//! lowers to generic IR (shuffles, compares, element access, plain
//! arithmetic) are lowered here, as `CodeGenFunction::EmitX86BuiltinExpr`
//! does, and the AVX to AVX-512 ones in [`crate::x86_gen`] (WP-1242).
//! The few x86 builtins kiln does not lower are in
//! [`crate::builtins::UNLOWERED_BUILTINS`], so `__has_builtin` is 0 for
//! them.

use kiln_ast::ExprId;
use kiln_ast::decl::builtin as id;
use kiln_ast::decl::builtin::x86;
pub(crate) use kiln_llvm::intrinsics::TargetMem as Mem;
use kiln_llvm::{BinOp, CastOp, Flags, FloatPredicate, TypeId as LTy, intrinsics};

use crate::builtins::BuiltinCall;
use crate::fir::{Fir, Op, V};
use crate::module::{Cg, R, err};

/// A builtin clang lowers to one `llvm.x86.*` call taking the builtin's
/// arguments in order: a row of [`crate::x86_intrinsics::MAP`], decoded.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Map {
    /// The builtin.
    pub name: &'static str,
    /// The intrinsic's full name.
    pub intr: &'static str,
    /// The intrinsic's return type, as LLVM prints it.
    pub ret: &'static str,
    /// The intrinsic's parameter types, as LLVM prints them (`, `
    /// separated; an `immarg` parameter is followed by ` immarg`).
    pub params: &'static str,
    /// The intrinsic's attributes.
    pub mem: Mem,
}

/// A row of the generated table: `(offset, length)` of the builtin, the
/// intrinsic, the return type and the parameter types in
/// `x86_intrinsics::STRS`, and the attributes. No pointers, so the table
/// needs no load-time relocation (WP-660).
#[derive(Clone, Copy, Debug)]
pub(crate) struct Packed {
    name: u32,
    intr: u32,
    ret: u32,
    params: u32,
    name_len: u8,
    intr_len: u8,
    ret_len: u8,
    params_len: u8,
    mem: Mem,
}

pub(crate) const fn p(
    name: (u32, u8),
    intr: (u32, u8),
    ret: (u32, u8),
    params: (u32, u8),
    mem: Mem,
) -> Packed {
    Packed {
        name: name.0,
        intr: intr.0,
        ret: ret.0,
        params: params.0,
        name_len: name.1,
        intr_len: intr.1,
        ret_len: ret.1,
        params_len: params.1,
        mem,
    }
}

/// The `len` bytes of the string blob at `at` (ASCII, so any range is on
/// character boundaries).
fn text(at: u32, len: u8) -> &'static str {
    let at = at as usize;
    &crate::x86_intrinsics::STRS[at..at + usize::from(len)]
}

fn decode(p: &Packed) -> Map {
    Map {
        name: text(p.name, p.name_len),
        intr: text(p.intr, p.intr_len),
        ret: text(p.ret, p.ret_len),
        params: text(p.params, p.params_len),
        mem: p.mem,
    }
}

/// The number of 1:1 lowerings.
pub fn len() -> usize {
    crate::x86_intrinsics::MAP.len()
}

/// Every 1:1 lowering, sorted by builtin name.
pub fn rows() -> impl ExactSizeIterator<Item = Map> {
    crate::x86_intrinsics::MAP.iter().map(decode)
}

/// The 1:1 lowering of builtin `name` (a binary search over the sorted
/// names).
pub fn by_name(name: &str) -> Option<Map> {
    let t = &crate::x86_intrinsics::MAP;
    let i = t.binary_search_by(|p| text(p.name, p.name_len).cmp(name)).ok()?;
    Some(decode(&t[i]))
}

/// The predicate of an SSE `cmp<cc>ps` / `cmp<cc>pd` builtin's condition
/// (clang `getVectorFCmpIR` operands).
fn named_cmp(cc: &str) -> Option<(FloatPredicate, u8)> {
    use FloatPredicate::{Oeq, Ole, Olt, Ord, Uge, Ugt, Une, Uno};
    Some(match cc {
        "eq" => (Oeq, 0),
        "lt" => (Olt, 1),
        "le" => (Ole, 2),
        "unord" => (Uno, 3),
        "neq" => (Une, 4),
        "nlt" => (Uge, 5),
        "nle" => (Ugt, 6),
        "ord" => (Ord, 7),
        _ => return None,
    })
}

/// The `fcmp` predicate of a `cmpps` / `cmppd` immediate (its low four
/// bits; the signalling behaviour bit 4 selects is not modelled, as in
/// clang without strict floating point).
pub(crate) fn imm_cmp(cc: u32) -> FloatPredicate {
    use FloatPredicate::{
        False, Oeq, Oge, Ogt, Ole, Olt, One, Ord, True, Ueq, Uge, Ugt, Ule, Ult, Une, Uno,
    };
    [Oeq, Olt, Ole, Uno, Une, Uge, Ugt, Ord, Ueq, Ult, Ule, False, One, Oge, Ogt, True]
        [(cc & 0xf) as usize]
}

impl Cg<'_> {
    /// The call `e` of x86 builtin `b`. A feature the calling function
    /// lacks is `err_builtin_needs_feature` and the call's value poison
    /// (emission continues; the driver fails on the error).
    pub(crate) fn emit_x86_builtin(&mut self, b: u32, e: ExprId) -> R<BuiltinCall> {
        let ast = self.ast;
        let Some(row) = x86::row(b) else {
            return err(self.loc_of(e), "not an x86 builtin");
        };
        let rty = self.lty(ast.exprs.get(e).ty());
        let args: Vec<ExprId> = ast.lists.iter(ast.exprs.call_args(e)).collect();
        if !self.x86_builtin_features_ok(&row, e, &args) {
            let p = if rty == LTy::VOID { None } else { Some(V::C(self.m.const_poison(rty))) };
            return Ok(BuiltinCall::Emitted(p));
        }
        let name = row.info.name;
        let short = name.strip_prefix(x86::PREFIX).unwrap_or(name);
        let width =
            crate::x86_gen::required_width(short, row.info.sig, self.opts.clang_compat >= 22);
        self.f.vector_width = self.f.vector_width.max(width);
        if let Some(v) = self.x86_custom(name, e, &args, rty)? {
            return Ok(BuiltinCall::Emitted(v));
        }
        if let Some(map) = by_name(name) {
            return self.x86_mapped(&map, b, e, &args, rty).map(BuiltinCall::Emitted);
        }
        if let Some(v) = self.x86_generic(b, short, e, &args, rty)? {
            return Ok(BuiltinCall::Emitted(v));
        }
        err(self.loc_of(e), format!("code generation for {name} is not supported yet"))
    }

    /// The return and parameter types of the 1:1 lowering `map` (`None`:
    /// a type kiln does not parse).
    fn x86_map_types(&mut self, map: &Map) -> Option<(LTy, Vec<(LTy, bool)>)> {
        let ret = self.x86_llvm_ty(map.ret)?;
        let mut params = Vec::new();
        for p in map.params.split(", ").filter(|p| !p.is_empty()) {
            let (t, imm) = match p.strip_suffix(" immarg") {
                Some(t) => (t, true),
                None => (p, false),
            };
            params.push((self.x86_llvm_ty(t)?, imm));
        }
        Some((ret, params))
    }

    /// The intrinsic call the 1:1 builtin `name` lowers to, on operands
    /// already emitted (each bitcast to the intrinsic's parameter type);
    /// for the lowerings built on another builtin (`x86_mmx`).
    pub(crate) fn x86_call_builtin(&mut self, name: &str, ops: Vec<V>, e: ExprId) -> R<V> {
        let Some(map) = by_name(name) else {
            return err(self.loc_of(e), format!("no lowering for {name}"));
        };
        let Some((ret, params)) = self.x86_map_types(&map) else {
            return err(self.loc_of(e), format!("bad intrinsic type for {name}"));
        };
        if params.len() != ops.len() {
            return err(self.loc_of(e), format!("wrong operand count for {name}"));
        }
        let mut vals = Vec::with_capacity(ops.len());
        for (v, &(pty, _)) in ops.into_iter().zip(&params) {
            let vt = self.f.fir.ty(&self.m, v);
            vals.push(self.x86_bitcast(v, vt, pty, e)?);
        }
        let f = intrinsics::target_intrinsic(&mut self.m, map.intr, ret, &params, map.mem);
        Ok(self.intrinsic_call(f, vals))
    }

    /// An LLVM type as the table prints it (`i32`, `<4 x float>`, `ptr`).
    fn x86_llvm_ty(&mut self, s: &str) -> Option<LTy> {
        let s = s.trim();
        if let Some(v) = s.strip_prefix('<').and_then(|v| v.strip_suffix('>')) {
            let (n, et) = v.split_once(" x ")?;
            let et = self.x86_llvm_ty(et)?;
            return Some(self.m.types.vector(et, n.parse().ok()?));
        }
        Some(match s {
            "void" => LTy::VOID,
            "half" => LTy::HALF,
            "bfloat" => LTy::BFLOAT,
            "float" => LTy::FLOAT,
            "double" => LTy::DOUBLE,
            "ptr" => self.m.types.ptr(0),
            _ => self.m.types.int(s.strip_prefix('i')?.parse().ok()?),
        })
    }

    /// The width in bits of a first-class type of an x86 operand.
    pub(crate) fn x86_bits(&self, t: LTy) -> Option<u32> {
        let scalar = |t: LTy| match t {
            LTy::HALF | LTy::BFLOAT => Some(16),
            LTy::FLOAT => Some(32),
            LTy::DOUBLE => Some(64),
            _ if t == LTy::PTR => Some(64),
            _ => self.m.types.int_width(t),
        };
        match self.m.types.vector_info(t) {
            Some((e, n, false)) => scalar(e).map(|b| b * n),
            Some((_, _, true)) => None,
            None => scalar(t),
        }
    }

    /// `v` (of type `from`) as type `to`: clang's `CreateBitCast` between
    /// types of the same width.
    pub(crate) fn x86_bitcast(&mut self, v: V, from: LTy, to: LTy, e: ExprId) -> R<V> {
        if from == to {
            return Ok(v);
        }
        match (self.x86_bits(from), self.x86_bits(to)) {
            (Some(a), Some(b)) if a == b => Ok(self.cast(CastOp::BitCast, v, to)),
            _ => err(self.loc_of(e), "x86 builtin operand has an unexpected type"),
        }
    }

    /// The constant value of the integer constant argument `a`.
    pub(crate) fn x86_imm(&mut self, a: ExprId) -> R<i128> {
        match self.fold_int(a) {
            Some(v) => Ok(v),
            None => err(self.loc_of(a), "x86 builtin immediate is not a constant"),
        }
    }

    /// clang's generic `ClangBuiltin` lowering: every argument (an integer
    /// constant one as a constant of the intrinsic's parameter type),
    /// each bitcast to the intrinsic's parameter type, the call, and the
    /// result bitcast to the builtin's type.
    fn x86_mapped(
        &mut self,
        map: &Map,
        b: u32,
        e: ExprId,
        args: &[ExprId],
        rty: LTy,
    ) -> R<Option<V>> {
        let Some((ret, params)) = self.x86_map_types(map) else {
            return err(self.loc_of(e), format!("bad intrinsic type for {}", map.name));
        };
        if params.len() != args.len() {
            return err(self.loc_of(e), format!("wrong argument count for {}", map.name));
        }
        let ice = id::ice_params(b);
        let mut vals = Vec::with_capacity(args.len());
        for (i, (&a, &(pty, _))) in args.iter().zip(&params).enumerate() {
            if ice & (1 << i) != 0 && self.m.types.int_width(pty).is_some() {
                let c = self.x86_imm(a)?;
                vals.push(V::C(self.m.const_int(pty, c)));
                continue;
            }
            let v = self.emit_scalar(a)?;
            vals.push(v);
        }
        for ((v, &a), &(pty, _)) in vals.iter_mut().zip(args).zip(&params) {
            let aty = self.f.fir.ty(&self.m, *v);
            if aty != pty {
                *v = self.x86_bitcast(*v, aty, pty, a)?;
            }
        }
        let f = intrinsics::target_intrinsic(&mut self.m, map.intr, ret, &params, map.mem);
        let r = self.intrinsic_call(f, vals);
        if ret == LTy::VOID {
            return Ok(None);
        }
        Ok(Some(self.x86_bitcast(r, ret, rty, e)?))
    }

    /// The builtins clang lowers to generic IR (or with a changed operand
    /// list): `None` when `name` is not one of them.
    #[allow(clippy::too_many_lines, reason = "one arm per builtin family, as clang's switch")]
    #[allow(
        clippy::option_option,
        reason = "outer: lowered here or not; inner: the call's value, `None` when void"
    )]
    fn x86_custom(
        &mut self,
        name: &str,
        e: ExprId,
        args: &[ExprId],
        rty: LTy,
    ) -> R<Option<Option<V>>> {
        let n = name.strip_prefix(x86::PREFIX).unwrap_or(name);
        if let Some(v) = self.x86_mmx(n, e, args, rty)? {
            return Ok(Some(v));
        }
        let arg = |s: &mut Self, i: usize| -> R<V> {
            match args.get(i) {
                Some(&a) => s.emit_scalar(a),
                None => err(s.loc_of(e), format!("too few arguments to {name}")),
            }
        };
        let imm = |s: &mut Self, i: usize| -> R<u32> {
            match args.get(i) {
                Some(&a) => Ok(s.x86_imm(a)? as u32),
                None => err(s.loc_of(e), format!("too few arguments to {name}")),
            }
        };
        // `cmp<cc>{ps,pd}`: an `fcmp`, sign-extended and bitcast back;
        // `cmp<cc>{ss,sd}`: `llvm.x86.sse{,2}.cmp.s{s,d}` with the
        // condition as the immediate.
        if let Some(rest) = n.strip_prefix("cmp")
            && let Some((cc, sfx)) = rest.split_at_checked(rest.len().saturating_sub(2))
            && let Some((p, k)) = named_cmp(cc)
        {
            let (a, b) = (arg(self, 0)?, arg(self, 1)?);
            return Ok(Some(Some(match sfx {
                "ps" | "pd" => self.x86_vector_fcmp(p, a, b, rty),
                _ => {
                    let intr =
                        if sfx == "ss" { "llvm.x86.sse.cmp.ss" } else { "llvm.x86.sse2.cmp.sd" };
                    let params = [(rty, false), (rty, false), (LTy::I8, true)];
                    let f =
                        intrinsics::target_intrinsic(&mut self.m, intr, rty, &params, Mem::None);
                    let k = V::C(self.m.const_int(LTy::I8, i128::from(k)));
                    self.intrinsic_call(f, vec![a, b, k])
                }
            })));
        }
        let v = match n {
            // clang: predicates 0 to 31 as `fcmp` (above 7 needs AVX,
            // checked with the features).
            "cmpps" | "cmppd" | "cmpps256" | "cmppd256" => {
                let (a, b) = (arg(self, 0)?, arg(self, 1)?);
                let cc = imm(self, 2)?;
                self.x86_vector_fcmp(imm_cmp(cc), a, b, rty)
            }
            "sqrtps" | "sqrtpd" | "sqrtps256" | "sqrtpd256" => {
                let a = arg(self, 0)?;
                let f = intrinsics::fp_op(&mut self.m, "llvm.sqrt", rty, 1);
                self.intrinsic_call(f, vec![a])
            }
            // The low element's square root, inserted back.
            "sqrtss" | "sqrtsd" => {
                let a = arg(self, 0)?;
                let zero = V::C(self.m.const_int(LTy::I64, 0));
                let x = self.extract_elt(a, zero);
                let et = self.f.fir.ty(&self.m, x);
                let f = intrinsics::fp_op(&mut self.m, "llvm.sqrt", et, 1);
                let r = self.intrinsic_call(f, vec![x]);
                self.insert_elt(a, r, zero)
            }
            "shufps" | "shufpd" | "shufps256" | "shufpd256" | "shufps512" | "shufpd512" => {
                let (a, b) = (arg(self, 0)?, arg(self, 1)?);
                // The immediate repeated per 128-bit lane.
                let mut im = (imm(self, 2)? & 0xff) * 0x0101_0101;
                let (_, total) = self.x86_lanes(rty);
                let per_lane = 128 / self.x86_elt_bits(rty);
                let mut mask = Vec::with_capacity(total as usize);
                for l in (0..total).step_by(per_lane as usize) {
                    for i in 0..per_lane {
                        let mut idx = im % per_lane + l;
                        im /= per_lane;
                        if i >= per_lane / 2 {
                            idx += total;
                        }
                        mask.push(idx);
                    }
                }
                self.shuffle(a, Some(b), mask)
            }
            "pshufd" | "pshufd256" | "pshufd512" => {
                let a = arg(self, 0)?;
                let im = imm(self, 1)?;
                let (_, total) = self.x86_lanes(rty);
                let mask = (0..total).map(|i| (i & !3) + ((im >> (2 * (i & 3))) & 3)).collect();
                self.shuffle(a, None, mask)
            }
            "pshuflw" | "pshufhw" | "pshuflw256" | "pshufhw256" | "pshuflw512" | "pshufhw512" => {
                let a = arg(self, 0)?;
                let im = imm(self, 1)?;
                let (_, total) = self.x86_lanes(rty);
                let low = n.starts_with("pshufl");
                let mask = (0..total)
                    .map(|i| {
                        let shuffled = if low { i % 8 < 4 } else { i % 8 >= 4 };
                        if shuffled { (i & !3) + ((im >> (2 * (i & 3))) & 3) } else { i }
                    })
                    .collect();
                self.shuffle(a, None, mask)
            }
            "pslldqi128_byteshift"
            | "psrldqi128_byteshift"
            | "pslldqi256_byteshift"
            | "psrldqi256_byteshift"
            | "pslldqi512_byteshift"
            | "psrldqi512_byteshift" => {
                let a = arg(self, 0)?;
                let shift = imm(self, 1)? & 0xff;
                let left = n.starts_with("psll");
                self.x86_byteshift(a, shift, left, rty)
            }
            "palignr128" | "palignr256" | "palignr512" => {
                let (a, b) = (arg(self, 0)?, arg(self, 1)?);
                let shift = imm(self, 2)? & 0xff;
                self.x86_palignr(a, b, shift, rty)
            }
            "blendpd" | "blendps" | "pblendw128" | "blendpd256" | "blendps256" | "pblendw256"
            | "pblendd128" | "pblendd256" => {
                let (a, b) = (arg(self, 0)?, arg(self, 1)?);
                let im = imm(self, 2)?;
                let (_, total) = self.x86_lanes(rty);
                let pick = |i: u32| if (im >> (i % 8)) & 1 != 0 { total + i } else { i };
                let mask = (0..total).map(pick).collect();
                self.shuffle(a, Some(b), mask)
            }
            "pmuludq128" | "pmuldq128" | "pmuludq256" | "pmuldq256" | "pmuludq512"
            | "pmuldq512" => {
                let (a, b) = (arg(self, 0)?, arg(self, 1)?);
                self.x86_muldq(a, b, n.starts_with("pmuldq"), rty)
            }
            // The index modulo the element count (clang `Index &= NumElts - 1`).
            _ if n.starts_with("vec_ext_v") => {
                let a = arg(self, 0)?;
                let at = self.f.fir.ty(&self.m, a);
                let (_, count) = self.x86_lanes(at);
                let i = imm(self, 1)? & (count - 1);
                let i = V::C(self.m.const_int(LTy::I64, i128::from(i)));
                self.extract_elt(a, i)
            }
            _ if n.starts_with("vec_set_v") => {
                let (a, x) = (arg(self, 0)?, arg(self, 1)?);
                let (_, count) = self.x86_lanes(rty);
                let i = imm(self, 2)? & (count - 1);
                let i = V::C(self.m.const_int(LTy::I64, i128::from(i)));
                self.insert_elt(a, x, i)
            }
            // An unaligned nontemporal store of the scalar (the low
            // element of the vector for `movnts{s,d}`).
            "movnti" | "movnti64" | "movntss" | "movntsd" => {
                let p = arg(self, 0)?;
                let mut x = arg(self, 1)?;
                if n.starts_with("movnts") {
                    let zero = V::C(self.m.const_int(LTy::I64, 0));
                    x = self.extract_elt(x, zero);
                }
                let st = self.store(x, p, 1, false);
                self.mark_nontemporal(st)?;
                return Ok(Some(None));
            }
            // x86's "undef" is zero (clang: PR32176).
            "undef128" | "undef256" | "undef512" => V::C(self.m.const_zero(rty)),
            "rdrand16_step" | "rdrand32_step" | "rdrand64_step" | "rdseed16_step"
            | "rdseed32_step" | "rdseed64_step" => {
                let p = arg(self, 0)?;
                let (base, bits) = n.split_at(6);
                let w: u32 = bits.trim_end_matches("_step").parse().unwrap_or(32);
                let it = self.m.types.int(w);
                let intr = format!("llvm.x86.{base}.{w}");
                let pair = (it, LTy::I32, 0);
                self.x86_pair_call(&intr, pair, &[], vec![], Mem::Unknown, (p, u64::from(w / 8)))
            }
            "rdtscp" => {
                let p = arg(self, 0)?;
                let pair = (LTy::I64, LTy::I32, 1);
                self.x86_pair_call("llvm.x86.rdtscp", pair, &[], vec![], Mem::Unknown, (p, 4))
            }
            // `{i8, iN} llvm.x86.{addcarry,subborrow}.N(c, a, b)`: the sum
            // stored through the pointer, the carry returned.
            "addcarryx_u32" | "addcarryx_u64" | "subborrow_u32" | "subborrow_u64" => {
                let w: u32 = if n.ends_with("64") { 64 } else { 32 };
                let it = self.m.types.int(w);
                let op = if n.starts_with("add") { "addcarry" } else { "subborrow" };
                let ops = vec![arg(self, 0)?, arg(self, 1)?, arg(self, 2)?];
                let p = arg(self, 3)?;
                let intr = format!("llvm.x86.{op}.{w}");
                let params = [(LTy::I8, false), (it, false), (it, false)];
                let pair = (LTy::I8, it, 1);
                self.x86_pair_call(&intr, pair, &params, ops, Mem::None, (p, u64::from(w / 8)))
            }
            // `ctlz` / `cttz` defined at zero.
            "lzcnt_u16" | "lzcnt_u32" | "lzcnt_u64" | "tzcnt_u16" | "tzcnt_u32" | "tzcnt_u64" => {
                let x = arg(self, 0)?;
                let t = self.f.fir.ty(&self.m, x);
                let f = if n.starts_with('l') {
                    intrinsics::ctlz(&mut self.m, t)
                } else {
                    intrinsics::cttz(&mut self.m, t)
                };
                let no = V::C(self.m.const_bool(false));
                self.intrinsic_call(f, vec![x, no])
            }
            // clang: through a temporary.
            "_mm_getcsr" | "stmxcsr" => {
                let tmp = self.f.fir.alloca(LTy::I32, 4);
                let p = self.m.types.ptr(0);
                let params = [(p, false)];
                let f = intrinsics::target_intrinsic(
                    &mut self.m,
                    "llvm.x86.sse.stmxcsr",
                    LTy::VOID,
                    &params,
                    Mem::UnknownArgWrite,
                );
                self.intrinsic_call(f, vec![tmp]);
                self.load(LTy::I32, tmp, 4, false)
            }
            "_mm_setcsr" | "ldmxcsr" => {
                let x = arg(self, 0)?;
                let tmp = self.f.fir.alloca(LTy::I32, 4);
                self.store(x, tmp, 4, false);
                let p = self.m.types.ptr(0);
                let params = [(p, false)];
                let f = intrinsics::target_intrinsic(
                    &mut self.m,
                    "llvm.x86.sse.ldmxcsr",
                    LTy::VOID,
                    &params,
                    Mem::Unknown,
                );
                self.intrinsic_call(f, vec![tmp]);
                return Ok(Some(None));
            }
            _ => return Ok(None),
        };
        Ok(Some(Some(v)))
    }

    /// `!nontemporal !{i32 1}` on the load or store `inst`.
    pub(crate) fn mark_nontemporal(&mut self, inst: V) -> R<()> {
        let one = self.m.const_int(LTy::I32, 1);
        let md = self.m.md_const(one).map_err(|e| crate::consts::ir_err(&e))?;
        let node = self.m.md_tuple(&[Some(md)]);
        let kind = self.m.md_kind("nontemporal");
        self.f.fir.add_md(Fir::last_inst(inst), kind, node);
        Ok(())
    }

    /// The element type and count of vector type `t` (`(t, 1)` for a
    /// scalar).
    pub(crate) fn x86_lanes(&self, t: LTy) -> (LTy, u32) {
        self.m.types.vector_info(t).map_or((t, 1), |(e, n, _)| (e, n))
    }

    /// The element width of vector type `t`.
    pub(crate) fn x86_elt_bits(&self, t: LTy) -> u32 {
        let (e, _) = self.x86_lanes(t);
        self.x86_bits(e).unwrap_or(32)
    }

    /// clang `getVectorFCmpIR`: `fcmp p a, b`, sign-extended to the
    /// same-width integer vector, bitcast to the result type.
    fn x86_vector_fcmp(&mut self, p: FloatPredicate, a: V, b: V, rty: LTy) -> V {
        let c = self.fcmp(p, a, b);
        let (_, n) = self.x86_lanes(rty);
        let w = self.x86_elt_bits(rty);
        let it = self.m.types.int(w);
        let ivt = self.m.types.vector(it, n);
        let s = self.cast(CastOp::SExt, c, ivt);
        self.cast(CastOp::BitCast, s, rty)
    }

    /// clang's `pslldqi*_byteshift` / `psrldqi*_byteshift`: a byte shuffle
    /// with zero per 128-bit lane, zero for a shift above 15.
    pub(crate) fn x86_byteshift(&mut self, a: V, shift: u32, left: bool, rty: LTy) -> V {
        let (_, n64) = self.x86_lanes(rty);
        let total = n64 * 8;
        if shift >= 16 {
            return V::C(self.m.const_zero(rty));
        }
        let mut mask = Vec::with_capacity(total as usize);
        for l in (0..total).step_by(16) {
            for i in 0..16 {
                let idx = if left {
                    let idx = total + i - shift;
                    if idx < total { idx - (total - 16) } else { idx }
                } else {
                    let idx = i + shift;
                    if idx >= 16 { idx + total - 16 } else { idx }
                };
                mask.push(idx + l);
            }
        }
        let bt = self.m.types.vector(LTy::I8, total);
        let cast = self.cast(CastOp::BitCast, a, bt);
        let zero = V::C(self.m.const_zero(bt));
        let sv = if left {
            self.shuffle(zero, Some(cast), mask)
        } else {
            self.shuffle(cast, Some(zero), mask)
        };
        self.cast(CastOp::BitCast, sv, rty)
    }

    /// clang's `palignr*`: a byte shuffle of `b` then `a` per 128-bit lane
    /// (shifting in zeroes past one lane, zero past two).
    fn x86_palignr(&mut self, a: V, b: V, shift: u32, rty: LTy) -> V {
        let (_, total) = self.x86_lanes(rty);
        if shift >= 32 {
            return V::C(self.m.const_zero(rty));
        }
        let (a, b, shift) =
            if shift > 16 { (V::C(self.m.const_zero(rty)), a, shift - 16) } else { (a, b, shift) };
        let mut mask = Vec::with_capacity(total as usize);
        for l in (0..total).step_by(16) {
            for i in 0..16 {
                let mut idx = shift + i;
                if idx >= 16 {
                    idx += total - 16;
                }
                mask.push(idx + l);
            }
        }
        self.shuffle(b, Some(a), mask)
    }

    /// clang `EmitX86Muldq`: the even 32-bit elements of `a` and `b`,
    /// sign- or zero-extended in 64-bit lanes, multiplied.
    pub(crate) fn x86_muldq(&mut self, a: V, b: V, signed: bool, rty: LTy) -> V {
        let a = self.cast(CastOp::BitCast, a, rty);
        let b = self.cast(CastOp::BitCast, b, rty);
        let (_, n) = self.x86_lanes(rty);
        let splat = |s: &mut Self, x: i128| {
            let k = s.m.const_int(LTy::I64, x);
            s.m.const_vector(&vec![k; n as usize]).map_or(V::C(k), V::C)
        };
        let (a, b) = if signed {
            let k = splat(self, 32);
            let a = self.bin(BinOp::Shl, Flags::NONE, a, k);
            let a = self.bin(BinOp::AShr, Flags::NONE, a, k);
            let b = self.bin(BinOp::Shl, Flags::NONE, b, k);
            let b = self.bin(BinOp::AShr, Flags::NONE, b, k);
            (a, b)
        } else {
            let k = splat(self, 0xffff_ffff);
            let a = self.bin(BinOp::And, Flags::NONE, a, k);
            let b = self.bin(BinOp::And, Flags::NONE, b, k);
            (a, b)
        };
        self.bin(BinOp::Mul, Flags::NONE, a, b)
    }

    /// A call of the target intrinsic `intr` returning `{a, b}` (`pair` =
    /// `(a, b, k)`): field `k` is stored through `to` (pointer, alignment),
    /// then the other field is the value, in clang's order.
    fn x86_pair_call(
        &mut self,
        intr: &str,
        pair: (LTy, LTy, u32),
        params: &[(LTy, bool)],
        ops: Vec<V>,
        mem: Mem,
        to: (V, u64),
    ) -> V {
        let (a, b, k) = pair;
        let st = self.m.types.struct_literal(&[a, b], false);
        let f = intrinsics::target_intrinsic(&mut self.m, intr, st, params, mem);
        let r = self.intrinsic_call(f, ops);
        let (stored, kept) = if k == 0 { (a, b) } else { (b, a) };
        let s = self.f.fir.push(Op::ExtractValue { agg: r, idx: k }, stored);
        self.store(s, to.0, to.1, false);
        self.f.fir.push(Op::ExtractValue { agg: r, idx: 1 - k }, kept)
    }
}
